const test=require('node:test'),assert=require('node:assert/strict');require('../drawing-language.js');const M=require('../drawing-methods.js');
test('all subjects render deterministically in each method and keep finite mark coordinates',()=>{for(const subject of M.subjects)for(const method of Object.keys(M.methods)){const a=M.build(subject.id,41,method),b=M.build(subject.id,41,method);assert.deepEqual(a,b,subject.id+' '+method);assert(a.strokes.length>0);for(const stroke of a.strokes)for(const mark of stroke.marks){assert(!/NaN|Infinity|undefined/.test(JSON.stringify(mark)),subject.id+' invalid geometry');}}});
test('new renderers share their plan and changing media never changes subject geometry',()=>{for(const subject of M.subjects){const plan=M.plan(subject.id,41),before=JSON.stringify(plan);for(const tool of ['pen','pencil','brush']){const output=M.render(plan,'simulation',tool);assert.equal(output.strokes.length,plan.items.length);assert.equal(JSON.stringify(plan),before);}assert.notDeepEqual(plan,M.plan(subject.id,42));}});
test('existing Current studies retain the original renderer exactly',()=>{for(const subject of DrawingLanguage.subjects)assert.deepEqual(M.build(subject.id,41,'current'),DrawingLanguage.build(subject.id,41));});
test('gesture and hand tools produce distinct marks for the same geometry',()=>{const p=M.plan('fern',41);const variants=[M.render(p,'gesture'),...['pen','pencil','brush'].map(t=>M.render(p,'simulation',t))];assert.equal(new Set(variants.map(v=>JSON.stringify(v.layers))).size,4);});
